// Prepara el email para el subflujo 'Enviador de emails'.
// Entrada: item del Webhook (POST /Colaborador). El payload llega en .body:
//   { evento, colaborador:{id,nombre,apellido,email,email_personal,whatsapp}, factura:{...} }
// colaborador.email_personal viene de la app (apsol_usuarios.email_personal):
// es adonde se le avisan los pagos. Si viene vacio, cae al email de la app.
// Salida: { emails_to, email_asunto, email_html }

// A quien se avisa cuando un colaborador sube una factura (quien registra los pagos).
const EMAIL_ADMIN = 'a_patriarca@hotmail.com';

const src = $input.first().json;
const p = src && src.body ? src.body : src;
const evento = p.evento;
const colaborador = p.colaborador || {};
const factura = p.factura || {};

const emailPersonal = String(colaborador.email_personal || '').trim() || colaborador.email || '';

const fmtMonto = (n) => '$ ' + Number(n || 0).toLocaleString('es-AR', { minimumFractionDigits: 2 });
const fmtFecha = (f) => f ? String(f).split('T')[0].split('-').reverse().join('/') : '—';
const nombreColab = [colaborador.nombre, colaborador.apellido].filter(Boolean).join(' ') || 'El colaborador';

let emails_to, email_asunto, email_html;

if (evento === 'colaborador_subio_factura') {
  emails_to = EMAIL_ADMIN;
  email_asunto = `🧾 ${nombreColab} subió una factura — ${fmtMonto(factura.monto)}`;
  email_html = `
<div style='font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#0f172a'>
  <p><strong>${nombreColab}</strong> subió una factura para cobrar.</p>
  <table style='border-collapse:collapse;margin:12px 0'>
    <tr><td style='padding:4px 12px 4px 0;color:#475569'>Nº de factura</td><td style='padding:4px 0'>${factura.numero_factura || '—'}</td></tr>
    <tr><td style='padding:4px 12px 4px 0;color:#475569'>Fecha de la factura</td><td style='padding:4px 0'>${fmtFecha(factura.fecha_factura)}</td></tr>
    <tr><td style='padding:4px 12px 4px 0;color:#475569'>Monto</td><td style='padding:4px 0'><strong>${fmtMonto(factura.monto)}</strong></td></tr>
  </table>
  ${factura.archivo_factura ? `<p><a href='${factura.archivo_factura}' style='color:#e06200'>Ver PDF de la factura</a></p>` : ''}
  <p style='margin-top:16px'>Entrá a la ficha del colaborador en Gestión APSOL para registrar el pago.</p>
</div>`.trim();
} else if (evento === 'pago_colaborador_registrado') {
  emails_to = emailPersonal;
  email_asunto = `✅ Te registramos el pago de tu factura — ${fmtMonto(factura.monto)}`;
  email_html = `
<div style='font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#0f172a'>
  <p>Hola ${colaborador.nombre || ''},</p>
  <p>Registramos el pago de tu factura.</p>
  <table style='border-collapse:collapse;margin:12px 0'>
    <tr><td style='padding:4px 12px 4px 0;color:#475569'>Nº de factura</td><td style='padding:4px 0'>${factura.numero_factura || '—'}</td></tr>
    <tr><td style='padding:4px 12px 4px 0;color:#475569'>Fecha de pago</td><td style='padding:4px 0'>${fmtFecha(factura.fecha_pago)}</td></tr>
    <tr><td style='padding:4px 12px 4px 0;color:#475569'>Monto</td><td style='padding:4px 0'><strong>${fmtMonto(factura.monto)}</strong></td></tr>
  </table>
  ${factura.comprobante_pago ? `<p><a href='${factura.comprobante_pago}' style='color:#e06200'>Ver comprobante de pago</a></p>` : ''}
  <p style='margin-top:16px'>Saludos,<br/>APSOL</p>
</div>`.trim();
} else {
  return [];
}

if (!emails_to) {
  throw new Error('Sin destinatario para el evento ' + evento + ' (colaborador sin email ni email_personal)');
}

return [{ json: { emails_to, email_asunto, email_html } }];
